description:
# nukkit-coroutines

Coroutine support utilities for PowerNukkitX plugins.

## Requirements

- Java 21+ (the DB dispatcher uses virtual threads)

## Installation
Add the snapshot repository and dependencies in your plugin project.

```kotlin
repositories {
    maven("https://repo.minjae.dev/snapshots")
}

dependencies {
    implementation("dev.minjae.nukkit:nukkit-coroutines-api:1.0-SNAPSHOT")
    implementation("dev.minjae.nukkit:nukkit-coroutines-core:1.0-SNAPSHOT")
}
```

## Simple Usage (Plugin)

```kotlin
import dev.minjae.nukkit.SuspendingPlugin
import dev.minjae.nukkit.asyncDispatcher
import dev.minjae.nukkit.launch
import dev.minjae.nukkit.nukkitDispatcher
import dev.minjae.nukkit.ticks
import kotlinx.coroutines.delay
import kotlinx.coroutines.withContext

class MyPlugin : SuspendingPlugin() {
    override suspend fun onEnableAsync() {
        launch(asyncDispatcher) {
            val result = "background work"
            withContext(nukkitDispatcher) {
                logger.info("Result: $result")
            }
        }

        launch {
            delay(20.ticks)
            logger.info("Ran after 20 ticks")
        }
    }
}
```

You can also register suspending listeners with `registerSuspendingEvents(listener)` and use `SuspendingCommand` for suspendable command handlers.

## Event Listener Example

```kotlin
import cn.nukkit.event.EventHandler
import cn.nukkit.event.Listener
import cn.nukkit.event.player.PlayerJoinEvent
import dev.minjae.nukkit.SuspendingPlugin
import dev.minjae.nukkit.asyncDispatcher
import dev.minjae.nukkit.nukkitDispatcher
import kotlinx.coroutines.withContext

class JoinListener(private val plugin: SuspendingPlugin) : Listener {
    @EventHandler
    suspend fun onJoin(event: PlayerJoinEvent) {
        val message = withContext(plugin.asyncDispatcher) {
            // Simulate blocking I/O or DB work
            "Welcome, ${event.player.name}"
        }
        withContext(plugin.nukkitDispatcher) {
            event.player.sendMessage(message)
        }
    }
}

// In your plugin's onEnableAsync():
// registerSuspendingEvents(JoinListener(this))
```

## Command Example

```kotlin
import cn.nukkit.command.CommandSender
import dev.minjae.nukkit.SuspendingPlugin
import dev.minjae.nukkit.SuspendingCommand
import dev.minjae.nukkit.asyncDispatcher
import dev.minjae.nukkit.nukkitDispatcher
import kotlinx.coroutines.withContext

class StatsCommand(plugin: SuspendingPlugin) : SuspendingCommand(
    plugin = plugin,
    name = "stats",
    description = "Show player stats"
) {
    override suspend fun executeAsync(
        sender: CommandSender,
        commandLabel: String,
        args: Array<out String>
    ) {
        val result = withContext(plugin.asyncDispatcher) {
            // Do blocking lookup here
            "Kills: 10, Deaths: 2"
        }
        sender.sendMessage(result)
    }
}
```
